-- ================================================================
-- Reemplaza por completo el esquema_json de "Arrendamiento - Local
-- Comercial" con la version original correcta (verificada con
-- Python: 44 campos, dpi_arrendatario y direccion_arrendatario
-- reutilizados a proposito entre individual/juridica) mas los dos
-- campos de fecha agregados una sola vez.
--
-- Se usa esto en vez de mas cirugia con JSON_MODIFY/OPENJSON porque
-- el script anterior de limpieza de duplicados borro por error
-- dpi_arrendatario y direccion_arrendatario de la variante "Persona
-- juridica" (los trato como duplicados cuando en realidad son un
-- mismo nombre de campo reutilizado a proposito en dos ramas
-- condicionales distintas).
-- ================================================================
USE LegalGestiones;

UPDATE tipos_solicitud
SET esquema_json = N'{"roles_partes":[],"campos":[{"nombre":"seccion_sociedad","etiqueta":"SOCIEDAD ARRENDANTE","tipo":"seccion"},{"nombre":"sociedad_id","etiqueta":"Sociedad arrendante","tipo":"select","fuente":"sociedades","requerido":true},{"nombre":"seccion_inmueble","etiqueta":"INMUEBLE","tipo":"seccion"},{"nombre":"numero_locales","etiqueta":"Número de local","tipo":"text","requerido":true},{"nombre":"oficina","etiqueta":"Nombre del inmueble / edificio","tipo":"text","requerido":true},{"nombre":"direccion","etiqueta":"Dirección","tipo":"text","requerido":true},{"nombre":"metros_cuadrados","etiqueta":"Metros cuadrados","tipo":"number","requerido":true},{"nombre":"finca","etiqueta":"Finca","tipo":"text","requerido":false},{"nombre":"folio","etiqueta":"Folio","tipo":"text","requerido":false},{"nombre":"libro","etiqueta":"Libro","tipo":"text","requerido":false},{"nombre":"seccion_arrendatario","etiqueta":"ARRENDATARIO","tipo":"seccion"},{"nombre":"tipo_arrendatario","etiqueta":"Tipo de arrendatario","tipo":"select","opciones":["Persona individual","Persona jurídica"],"requerido":true},{"nombre":"nombre_arrendatario","etiqueta":"Nombre completo","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"edad_arrendatario","etiqueta":"Edad","tipo":"number","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"estado_civil_arrendatario","etiqueta":"Estado civil","tipo":"select","opciones":["Soltero/a","Casado/a","Divorciado/a","Viudo/a","Unión de hecho"],"requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"profesion_arrendatario","etiqueta":"Profesión u oficio","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"nacionalidad_arrendatario","etiqueta":"Nacionalidad","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"dpi_arrendatario","etiqueta":"DPI (CUI)","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"direccion_arrendatario","etiqueta":"Dirección","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"adjuntos_arrendatario_individual","etiqueta":"Documentos del arrendatario","tipo":"adjuntos","docs":["DPI","RTU","Recibo de servicios"],"requerido":true,"condicional":"tipo_arrendatario","valor":"Persona individual"},{"nombre":"nombre_razon_social","etiqueta":"Razón social","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona jurídica"},{"nombre":"nombre_representante_arrendatario","etiqueta":"Nombre del representante legal","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona jurídica"},{"nombre":"cargo_representante_arrendatario","etiqueta":"Cargo del representante legal","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona jurídica"},{"nombre":"dpi_arrendatario","etiqueta":"DPI del representante legal","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona jurídica"},{"nombre":"direccion_arrendatario","etiqueta":"Dirección","tipo":"text","requerido":true,"condicional":"tipo_arrendatario","valor":"Persona jurídica"},{"nombre":"adjuntos_arrendatario_juridica","etiqueta":"Documentos del arrendatario","tipo":"adjuntos","docs":["Representante legal (RL)","DPI","Patentes","Constitución de sociedad","Recibo de servicios"],"requerido":true,"condicional":"tipo_arrendatario","valor":"Persona jurídica"},{"nombre":"seccion_fiador","etiqueta":"FIADOR","tipo":"seccion"},{"nombre":"incluye_fiador","etiqueta":"¿Incluye fiador?","tipo":"boolean","requerido":false},{"nombre":"tipo_fiador","etiqueta":"Tipo de fiador","tipo":"select","opciones":["Persona individual","Persona jurídica"],"requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"nombre_fiador","etiqueta":"Nombre completo del fiador","tipo":"text","requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"edad_fiador","etiqueta":"Edad","tipo":"number","requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"estado_civil_fiador","etiqueta":"Estado civil","tipo":"select","opciones":["Soltero/a","Casado/a","Divorciado/a","Viudo/a","Unión de hecho"],"requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"profesion_fiador","etiqueta":"Profesión u oficio","tipo":"text","requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"nacionalidad_fiador","etiqueta":"Nacionalidad","tipo":"text","requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"dpi_fiador","etiqueta":"DPI del fiador","tipo":"text","requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"direccion_fiador","etiqueta":"Dirección del fiador","tipo":"text","requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"adjuntos_fiador_individual","etiqueta":"Documentos del fiador","tipo":"adjuntos","docs":["DPI","RTU","Recibo de servicios"],"requerido":false,"condicional":"incluye_fiador","valor":"Sí"},{"nombre":"seccion_condiciones","etiqueta":"CONDICIONES DEL CONTRATO","tipo":"seccion"},{"nombre":"destino_local","etiqueta":"Destino del local","tipo":"text","requerido":true},{"nombre":"renta","etiqueta":"Renta mensual (Q)","tipo":"number","requerido":true},{"nombre":"plazo_en_letras","etiqueta":"Plazo del contrato (en letras)","tipo":"text","requerido":true},{"nombre":"condiciones_de_entrega_local","etiqueta":"Condiciones de entrega","tipo":"textarea","requerido":false},{"nombre":"fecha_inicio_contrato","etiqueta":"Fecha de inicio del contrato","tipo":"date","requerido":true},{"nombre":"fecha_terminacion_contrato","etiqueta":"Fecha de terminación del contrato","tipo":"date","requerido":true}]}'
WHERE nombre = 'Arrendamiento - Local Comercial';

-- Verificacion 1: debe dar 44
SELECT COUNT(*) AS total_campos
FROM tipos_solicitud t
CROSS APPLY OPENJSON(t.esquema_json, '$.campos')
WHERE t.nombre = 'Arrendamiento - Local Comercial';

-- Verificacion 2: debe mostrar SOLO dpi_arrendatario (2) y direccion_arrendatario (2)
SELECT JSON_VALUE(value, '$.nombre') AS nombre_campo, COUNT(*) AS veces
FROM tipos_solicitud t
CROSS APPLY OPENJSON(t.esquema_json, '$.campos')
WHERE t.nombre = 'Arrendamiento - Local Comercial'
GROUP BY JSON_VALUE(value, '$.nombre')
HAVING COUNT(*) > 1;
GO
